INSERT INTO words VALUES('2579','1','fastenings','fastenings','5','застёжки, крепления, фиксирующие элементы','','Fudge’s finger slipped on the silver {fastenings} of his cloak.','2025-07-29 02:03:30','2026-02-24 16:36:33','16','15','0.6835151376980498');
