INSERT INTO words VALUES('2581','1','angrier','angrier','99','злее, сердитый','','The Azkaban guards have never yet failed…and they are {angrier} than I’ve ever seen them.”','2025-07-29 02:03:53','2026-01-17 12:52:14','100','100','0.3692744787496277');
INSERT INTO words VALUES('2582','1','uncomfortable','uncomfortable','99','неудобно / неловко','','Fudge was looking {uncomfortable}.','2025-07-29 02:04:03','2026-01-17 12:49:44','100','100','0.6477563992587444');
INSERT INTO words VALUES('2583','1','eagerly','eagerly','4','с усердием, жадно, нетерпеливый','','— “But you’re the Minister of Magic,” said Harry {eagerly}.','2025-07-29 02:04:13','2026-04-22 22:49:42','41','39','0.12336928688303501');
INSERT INTO words VALUES('2584','1','flatly','flatly','4','категорически, наотрез, монотонно/сухо, ровно','','— “No, I’m sorry, Harry, but rules are rules,” said Fudge {flatly}.','2025-07-29 02:04:28','2026-04-22 16:52:59','41','39','0.31249766360269643');
INSERT INTO words VALUES('2585','1','fact','fact','99','факт','','In {fact}, I think it’s best if you don’t…yes…well, I’ll be off.','2025-07-29 02:04:34','2025-07-29 02:04:34','100','100','0.31256404827587686');
INSERT INTO words VALUES('2586','1','Enjoy','enjoy','99','наслаждаться','','{Enjoy} your stay, Harry.”','2025-07-29 02:04:47','2026-02-21 13:03:42','100','100','0.676156198304292');
INSERT INTO words VALUES('2587','1','follow','follow','4','следовать','','— “If you’ll {follow} me, Mr. Potter,” he said, “I’ve already taken your things up…”','2025-07-29 02:04:54','2026-04-23 18:20:07','43','41','0.19238048809802205');
