INSERT INTO words VALUES('2589','1','polished','polished','99','отполированная','','Inside was a very comfortable-looking bed, some highly {polished} oak furniture, a cheerfully crackling fire and, perched on top of the wardrobe —','2025-07-29 02:05:06','2026-04-23 12:54:23','100','100','0.9849132923268837');
