INSERT INTO words VALUES('2604','1','yawned','yawned','99','зевнул, зияла(пропасть)','','— “It’s been a very weird night, Hedwig,” he {yawned}.','2025-07-29 02:06:56','2026-04-22 22:52:41','100','100','0.5251750801924384');
INSERT INTO words VALUES('2605','1','removing','removing','5','снимая','','And without even {removing} his glasses, he slumped back onto his pillows and fell asleep.','2025-07-29 02:07:01','2026-02-20 13:42:13','10','9','0.20230177995031864');
