INSERT INTO words VALUES('2616','1','comfortable','comfortable','99','уютная на вид / выглядевшая удобной','','Inside was a very {comfortable}-looking bed, some highly polished oak furniture, a cheerfully crackling fire and, perched on top of the wardrobe —','2025-07-29 02:13:29','2026-01-17 13:02:53','100','100','0.3055126753687045');
