INSERT INTO words VALUES('2871','1','directive','directive','2','директива, указание, инструкция','','alias — In C#, there is another form of the using {directive} that allows you to create an alias for a specific type or namespace.','2025-08-27 22:41:20','2026-04-22 16:44:57','-4','-7','0.81718889327458');
INSERT INTO words VALUES('2872','1','create','create','99','создавать, формировать','','alias — In C#, there is another form of the using directive that allows you to {create} an alias for a specific type or namespace.','2025-08-27 22:41:30','2026-01-19 17:39:16','100','100','0.9908821936611851');
INSERT INTO words VALUES('2873','1','namespace','namespace','99','пространство имён','','alias — In C#, there is another form of the using directive that allows you to create an alias for a specific type or {namespace}.','2025-08-27 22:41:51','2026-01-18 12:42:07','100','100','0.02510304565085382');
INSERT INTO words VALUES('2874','1','versions','versions','99','версии, варианты','','extern alias — used when you need to use two different {versions} of the same library.','2025-08-27 22:42:25','2026-01-18 20:17:16','100','100','0.5494916695631031');
INSERT INTO words VALUES('2875','1','Операторы','операторы','99','*','','{Операторы} is и as, typeof','2025-08-27 22:56:38','2025-08-27 22:56:38','100','100','0.6630771753034341');
INSERT INTO words VALUES('2876','1','\'e\'','\'e\'','99','*','','It verifies the object\'s type only once, and then the if statement simply compares {\'e\'} to null — this check is much more efficient than determining the object\'s type.','2025-08-27 22:58:00','2025-08-27 22:58:00','100','100','0.1420965289157783');
INSERT INTO words VALUES('2877','1','int','int','99','*','','typeof({int}) // {int}','2025-08-27 22:58:54','2025-08-27 22:58:54','100','100','0.6072806609862303');
INSERT INTO words VALUES('2878','1','myType','mytype','99','*','','Type {myType} = typeof(Person);','2025-08-27 22:58:59','2025-08-27 22:58:59','100','100','0.31263830728143294');
INSERT INTO words VALUES('2879','1','casting','casting','5','приведение, преобразование','','Type {casting} is the mechanism for converting a value of one type to another.','2025-08-27 23:02:56','2026-02-14 13:09:06','2','1','0.8284495676201299');
INSERT INTO words VALUES('2880','1','mechanism','mechanism','4','механизм, способ, средство','','Type casting is the {mechanism} for converting a value of one type to another.','2025-08-27 23:03:02','2026-04-24 11:51:21','45','43','0.6906811890105542');
INSERT INTO words VALUES('2881','1','converting','converting','99','преобразование; преобразовывать','','Type casting is the mechanism for {converting} a value of one type to another.','2025-08-27 23:03:25','2026-01-18 20:02:09','100','100','0.15906808260741465');
INSERT INTO words VALUES('2882','1','conversions','conversions','3','преобразования','','C# supports several kinds of type {conversions}, such as:','2025-08-27 23:03:34','2026-04-22 22:27:00','13','11','0.9680572729260263');
INSERT INTO words VALUES('2883','1','kinds','kinds','5','виды, типы, разновидности','','C# supports several {kinds} of type conversions, such as:','2025-08-27 23:04:14','2026-02-22 13:48:01','13','12','0.7682428283321139');
INSERT INTO words VALUES('2884','1','Implicit','implicit','5','неявный','','{Implicit} conversions - in this case, no special syntax is required.','2025-08-27 23:04:26','2026-04-22 20:56:51','96','94','0.9370423536161355');
INSERT INTO words VALUES('2885','1','smaller','smaller','99','меньший, меньшего размера','','For example, conversions from {smaller} to larger integer types, or upcasting - converting from derived classes to base classes.','2025-08-27 23:04:36','2026-04-24 12:38:02','100','100','0.5582136861590796');
INSERT INTO words VALUES('2886','1','integer','integer','99','целочисленный, целый','','For example, conversions from smaller to larger {integer} types, or upcasting - converting from derived classes to base classes.','2025-08-27 23:04:46','2026-01-19 17:38:22','100','100','0.8656205570936395');
INSERT INTO words VALUES('2887','1','upcasting','upcasting','99','upcasting, восходящее приведение, апкаст','','With {upcasting}, methods not defined in the parent are unavailable.','2025-08-27 23:05:00','2026-01-19 15:51:55','100','100','0.38205440191743373');
INSERT INTO words VALUES('2888','1','base','base','99','базовый, основной; основывать','','For example, conversions from smaller to larger integer types, or upcasting - converting from derived classes to {base} classes.','2025-08-27 23:05:15','2026-01-18 20:10:06','100','100','0.806673523789899');
INSERT INTO words VALUES('2889','1','unavailable','unavailable','5','недоступны, недоступный','','With upcasting, methods not defined in the parent are {unavailable}.','2025-08-27 23:05:37','2026-02-23 13:24:13','15','13','0.380483313817981');
INSERT INTO words VALUES('2890','1','Explicit','explicit','99','явный, уточнённый','','{Explicit} casting - is required when data might be lost or the conversion might fail.','2025-08-27 23:06:09','2026-01-18 20:14:49','100','100','0.5448905439534136');
INSERT INTO words VALUES('2891','1','conversion','conversion','5','преобразование, приведение','','Explicit casting - is required when data might be lost or the {conversion} might fail.','2025-08-27 23:06:33','2026-02-26 16:03:36','19','17','0.09128953897514337');
INSERT INTO words VALUES('2892','1','fail','fail','5','отказ, сбой, неудача; провалиться, завершиться неудачей, отказать','','Explicit casting - is required when data might be lost or the conversion might {fail}.','2025-08-27 23:06:57','2026-03-04 13:14:36','27','26','0.3149977841554189');
INSERT INTO words VALUES('2893','1','Downcasting','downcasting','5','downcasting, нисходящее приведение, даункаст','','{Downcasting} is used to cast a type to one of its derived types.','2025-08-27 23:07:04','2026-02-14 13:06:33','2','1','0.30112033458530935');
INSERT INTO words VALUES('2894','1','cast','cast','99','приведение, преобразование; приводить (тип), преобразовывать','','Downcasting is used to {cast} a type to one of its derived types.','2025-08-27 23:07:24','2026-01-18 11:59:02','100','100','0.58075753094699');
INSERT INTO words VALUES('2895','1','require','require','99','требовать, требоваться; требовать, нуждаться','','Explicit conversions {require} a cast expression such as `is`, `as`, `typeof`, or `(T)`.','2025-08-27 23:07:41','2026-04-23 12:50:34','100','100','0.5042394963132585');
INSERT INTO words VALUES('2896','1','typeof','typeof','99','typeof, оператор typeof','','Explicit conversions require a cast expression such as `is`, `as`, `{typeof}`, or `(T)`.','2025-08-27 23:07:51','2026-04-24 12:41:10','100','100','0.786005941951653');
INSERT INTO words VALUES('2897','1','implemented','implemented','99','реализованы; реализовывать','','User-defined conversions - These are {implemented} as conversion operator methods using the operator keyword along with either implicit or explicit.','2025-08-27 23:08:12','2026-01-17 15:47:53','100','100','0.8016554748654883');
INSERT INTO words VALUES('2898','1','operator','operator','4','оператор, операнд, знак; оперировать','','User-defined conversions - These are implemented as conversion {operator} methods using the {operator} keyword along with either implicit or explicit.','2025-08-27 23:08:37','2026-04-22 22:55:05','41','39','0.560608351193935');
INSERT INTO words VALUES('2899','1','helper','helper','5','вспомогательный, помощник; помогать','','Conversions using {helper} classes, such as BitConverter, Convert, and methods like Parse and TryParse.','2025-08-27 23:09:04','2026-02-14 13:10:09','2','1','0.899680782947392');
