INSERT INTO words VALUES('2970','1','throw','throw','99','выбрасывать, генерировать, бросать','','It does not {throw} exceptions.','2025-08-29 22:11:25','2025-09-22 13:58:23','100','100','0.03733429781844309');
INSERT INTO words VALUES('2971','1','exceptions','exceptions','99','исключения, ошибки, отклонения','','It does not throw {exceptions}.','2025-08-29 22:11:34','2026-04-24 12:37:38','100','100','0.7541930123737017');
INSERT INTO words VALUES('2972','1','null','null','4','null, нуль, отсутствие значения','','If the object is {null}, the operator always returns false.','2025-08-29 22:11:41','2026-04-24 12:29:18','45','43','0.38385214133546885');
INSERT INTO words VALUES('2973','1','casts','casts','5','приводить (тип), преобразовывать','','The as operator {casts} an object to the specified type and returns a reference to the object, or null if the cast is not possible.','2025-08-29 22:12:39','2026-02-14 12:41:17','2','1','0.46952406174458944');
INSERT INTO words VALUES('2974','1','verifies','verifies','5','проверять, подтверждать, удостоверять','','It {verifies} the object\'s type only once, and then the if statement simply compares \'e\' to null — this check is much more efficient than determining the object\'s type.','2025-08-29 22:13:09','2026-02-27 13:47:27','20','19','0.19606391545018545');
INSERT INTO words VALUES('2975','1','statement','statement','5','оператор, инструкция, выражение; заявление, высказывание, утверждение','','It verifies the object\'s type only once, and then the if {statement} simply compares \'e\' to null — this check is much more efficient than determining the object\'s type.','2025-08-29 22:13:31','2026-02-22 13:42:54','13','12','0.571747422750804');
INSERT INTO words VALUES('2976','1','check','check','5','проверка, контроль; проверять, контролировать','','It verifies the object\'s type only once, and then the if statement simply compares \'e\' to null — this {check} is much more efficient than determining the object\'s type.','2025-08-29 22:13:49','2026-02-21 13:09:03','12','10','0.2705453981371088');
INSERT INTO words VALUES('2977','1','efficient','efficient','5','эффективный, результативный, действенный','','It verifies the object\'s type only once, and then the if statement simply compares \'e\' to null — this check is much more {efficient} than determining the object\'s type.','2025-08-29 22:14:03','2026-02-14 13:10:21','2','1','0.6374847531667769');
INSERT INTO words VALUES('2978','1','determining','determining','5','определение, установление; определять, устанавливать, выявлять','','It verifies the object\'s type only once, and then the if statement simply compares \'e\' to null — this check is much more efficient than {determining} the object\'s type.','2025-08-29 22:14:16','2026-03-03 18:59:00','26','24','0.3757876021562029');
INSERT INTO words VALUES('2979','1','obtains','obtains','3','получает, извлекает, приобретает; получать, извлекать, приобретать','','The typeof operator {obtains} a System.Type instance for the specified type.','2025-08-29 22:14:49','2026-04-22 20:57:13','13','11','0.9664837820143288');
INSERT INTO words VALUES('2980','1','takes','takes','99','принимает, берёт, получает; принимать, брать, получать','','The typeof(T) operator {takes} as an argument either a type name or a type parameter:','2025-08-29 22:15:09','2026-04-24 12:41:07','100','100','0.9451008922840477');
INSERT INTO words VALUES('2981','1','argument','argument','99','аргумент, параметр, довод','','The typeof(T) operator takes as an {argument} either a type name or a type parameter:','2025-08-29 22:15:37','2025-09-22 14:00:04','100','100','0.5634255423801258');
INSERT INTO words VALUES('2982','1','parameter','parameter','4','параметр, аргумент, характеристика','','The typeof(T) operator takes as an argument either a type name or a type {parameter}:','2025-08-29 22:15:50','2026-04-22 22:54:55','41','39','0.7050561343366804');
INSERT INTO words VALUES('2983','1','dynamic','dynamic','99','dynamic, динамический','','Can the argument be the {dynamic} type?','2025-08-29 22:16:03','2026-01-18 13:03:34','100','100','0.2184412565254059');
