INSERT INTO words VALUES('3001','1','specify','specify','99','указать, задать','','checked - is used when you want to {specify} that an expression should be checked for overflow.','2025-08-29 22:27:07','2026-04-23 12:53:54','100','100','0.5526493811538903');
