INSERT INTO words VALUES('3021','1','loss','loss','99','потеря, утрата, убыток; терять, утрачивать','','You can perform implicit conversions when no data {loss} can occur;','2025-08-29 22:48:57','2026-04-24 12:37:30','100','100','0.17516130225282284');
INSERT INTO words VALUES('3022','1','there\'s','there\'s','5','есть, имеется','','if {there\'s} a possibility of data loss, an explicit cast is required.','2025-08-29 22:49:06','2026-02-23 13:30:07','15','13','0.6037091534619304');
