INSERT INTO words VALUES('3032','1','affect','affect','99','влиять на, затрагивать','','Two variables of a reference type can refer to the same object, so operations on one variable can {affect} the other variable.','2025-08-29 23:19:39','2026-04-23 17:58:04','100','100','0.6697826801517817');
INSERT INTO words VALUES('3033','1','Additional','additional','99','дополнительный, добавочный, сверх-','','{Additional} members are subject to initialization;','2025-08-29 23:19:57','2026-01-19 17:43:27','100','100','0.03678288127927378');
