INSERT INTO words VALUES('3035','1','explicitly','explicitly','99','явно, недвусмысленно, прямо','','any fields not {explicitly} initialized are set to their default values (null or zero).','2025-08-29 23:20:19','2026-04-24 12:29:07','100','100','0.7004512992691726');
