INSERT INTO words VALUES('3037','1','default','default','99','по умолчанию','','any fields not explicitly initialized are set to their {default} values (null or zero).','2025-08-29 23:21:03','2026-01-19 15:53:50','100','100','0.40022078380009235');
INSERT INTO words VALUES('3038','1','zero','zero','3','ноль','','any fields not explicitly initialized are set to their default values (null or {zero}).','2025-08-29 23:21:12','2026-04-22 16:38:08','13','11','0.9368313978769177');
INSERT INTO words VALUES('3039','1','triggers','triggers','4','триггеры, инициаторы, пусковые механизмы; инициирует, запускает, вызывает','','Over time, a reference type {triggers} garbage collection.','2025-08-29 23:22:55','2026-04-24 11:46:54','45','43','0.988073276344755');
