INSERT INTO words VALUES('3122','1','resources','resources','99','ресурсы, средства, запасы','','A process is an instance of a program that has its own {resources} and virtual address space.','2025-08-30 02:14:24','2026-01-18 12:59:21','100','100','0.4200867381133947');
INSERT INTO words VALUES('3123','1','ensuring','ensuring','5','обеспечение, гарантирование; обеспечивать, гарантировать','','This isolates processes from each other, {ensuring} that one process cannot affect the data of another.','2025-08-30 02:14:41','2026-04-22 21:09:17','96','94','0.6393995821842919');
INSERT INTO words VALUES('3124','1','unit','unit','99','единица, блок, модуль','','A thread is a {unit} of execution that uses the resources of its process.','2025-08-30 02:14:48','2026-04-24 12:35:15','100','100','0.40953805056357573');
