INSERT INTO words VALUES('3239','1','modifier','modifier','99','модификатор, уточнение','','A static constructor is a constructor that has no access {modifier} or parameters, is marked with the static keyword, and is used to initialize the state of a type or perform an action that runs only once.','2025-08-30 20:35:59','2026-01-17 15:50:20','100','100','0.6110152952475616');
