INSERT INTO words VALUES('3280','1','extended','extended','5','расширяемый, продлённый; расширять, продлевать','','It is a static method that takes as its first parameter the type to be {extended}, marked with the `this` keyword, which indicates that this method is an extension method for the specified type.','2025-08-30 20:46:03','2026-02-15 13:16:23','3','2','0.40946924910831195');
