INSERT INTO words VALUES('3564','1','Constraints','constraints','99','ограничения','','{Constraints} can be applied to the type parameters of generic types and generic methods.','2025-08-31 20:32:27','2026-04-24 11:42:14','100','100','0.858356680589129');
INSERT INTO words VALUES('3565','1','rename','rename','99','переименовывать','','it may only {rename} the type parameters.','2025-08-31 20:32:27','2026-01-18 13:03:00','100','100','0.35178734394888145');
INSERT INTO words VALUES('3566','1','implementing','implementing','99','реализация, внедрение; реализовывать, внедрять','','The same applies when {implementing} an interface method: the {implementing} method\'s type parameters inherit the interface method\'s constraints.','2025-08-31 20:32:27','2026-01-17 20:59:16','100','100','0.7438447743131265');
INSERT INTO words VALUES('3567','1','method\'s','method\'s','99','метода','','The same applies when implementing an interface method: the implementing {method\'s} type parameters inherit the interface {method\'s} constraints.','2025-08-31 20:32:27','2026-01-18 12:49:47','100','100','0.4019287828373991');
INSERT INTO words VALUES('3568','1','Overloading','overloading','99','перегрузка, переопределение; перегружать','','{Overloading} by type parameter names or by constraints is not supported — only by arity (number of type parameters), for example:','2025-08-31 20:32:27','2026-01-18 20:03:24','100','100','0.8240779785663616');
INSERT INTO words VALUES('3569','1','arity','arity','3','арность, количество аргументов','','Overloading by type parameter names or by constraints is not supported — only by {arity} (number of type parameters), for example:','2025-08-31 20:32:27','2026-04-22 16:31:35','13','11','0.46934177025159984');
INSERT INTO words VALUES('3570','1','AType','atype','99','AType, тип A','','internal sealed class {AType} [ ]','2025-08-31 20:32:27','2025-09-02 14:49:33','100','100','0.11519600554853306');
INSERT INTO words VALUES('3571','1','primary','primary','99','основной, первичный, главный','','A type parameter can have the following constraints: {primary}, secondary, and/or the constructor constraint.','2025-08-31 20:32:27','2026-04-24 11:37:33','100','100','0.5312114195257531');
INSERT INTO words VALUES('3572','1','secondary','secondary','99','вторичный, второстепенный','','A type parameter can have the following constraints: primary, {secondary}, and/or the constructor constraint.','2025-08-31 20:32:27','2026-04-22 22:53:44','100','100','0.2941663696376294');
INSERT INTO words VALUES('3573','1','unsealed','unsealed','99','открытый, незапечатанный','','- A primary constraint can be an {unsealed} reference type, except for Object, Array, ValueType, and Void.','2025-08-31 20:32:27','2026-01-19 15:50:50','100','100','0.5377179948033001');
INSERT INTO words VALUES('3574','1','except','except','5','кроме','','- A primary constraint can be an unsealed reference type, {except} for Object, Array, ValueType, and Void.','2025-08-31 20:32:27','2026-02-23 13:22:22','15','13','0.770059463353883');
INSERT INTO words VALUES('3575','1','includes','includes','99','включать, содержать','','This {includes} all classes, interfaces, delegates, and arrays.','2025-08-31 20:32:27','2026-01-18 20:11:14','100','100','0.5555380550730397');
INSERT INTO words VALUES('3576','1','arrays','arrays','99','массивы','','This includes all classes, interfaces, delegates, and {arrays}.','2025-08-31 20:32:27','2026-04-23 18:43:04','100','100','0.18407529237128356');
INSERT INTO words VALUES('3577','1','recursion','recursion','5','рекурсия','','This includes all value types and enums, except for `Nullable<T>`, as this would result in {recursion}.','2025-08-31 20:32:27','2026-02-25 14:07:38','17','16','0.44227203674826027');
INSERT INTO words VALUES('3578','1','SomeClass','someclass','99','SomeClass, класс SomeClass','','public class {SomeClass} :','2025-08-31 20:32:27','2025-09-02 21:11:44','100','100','0.9680235618427615');
INSERT INTO words VALUES('3579','1','ISomeInterface','isomeinterface','99','ISomeInterface, интерфейс ISomeInterface','','{ISomeInterface}<MyClass> // interface constraint','2025-08-31 20:32:27','2025-09-07 16:53:46','100','100','0.08027046181286729');
INSERT INTO words VALUES('3580','1','MyClass','myclass','99','MyClass, мой класс','','ISomeInterface<{MyClass}> // interface constraint','2025-08-31 20:32:27','2025-09-02 01:35:56','100','100','0.055337245627620484');
INSERT INTO words VALUES('3581','1','guarantees','guarantees','5','гарантии; гарантировать,','','The constructor constraint (new()) {guarantees} the type argument is a non-abstract type that has a public parameterless constructor.','2025-08-31 20:32:27','2026-02-15 13:27:10','3','2','0.9011818244132975');
INSERT INTO words VALUES('3582','1','redundant','redundant','5','избыточный, лишний','','You cannot combine struct and new() because every struct implicitly has a public parameterless constructor, so specifying both is {redundant}.','2025-08-31 20:32:27','2026-02-14 13:10:57','2','1','0.17909304255535177');
INSERT INTO words VALUES('3583','1','signatures','signatures','5','сигнатуры, подписи','','A class can have only one direct base class, which provides a set of method {signatures} and implementations, and the new class can become a base for another class.','2025-08-31 20:32:27','2026-02-14 13:05:00','2','1','0.1919197702705113');
INSERT INTO words VALUES('3584','1','implementations','implementations','99','реализации, осуществление','','A class can have only one direct base class, which provides a set of method signatures and {implementations}, and the new class can become a base for another class.','2025-08-31 20:32:27','2026-01-17 15:54:11','100','100','0.0007009943953724526');
INSERT INTO words VALUES('3585','1','become','become','99','стать, становиться, делаться','','A class can have only one direct base class, which provides a set of method signatures and implementations, and the new class can {become} a base for another class.','2025-08-31 20:32:27','2026-01-19 17:56:03','100','100','0.5212988737237629');
INSERT INTO words VALUES('3586','1','substitute','substitute','5','замена, суррогат; заменять, подменять, подставлять','','Class inheritance allows you to {substitute} instances of a derived type in any context where instances of the base type are expected (upcasting).','2025-08-31 20:32:27','2026-02-14 13:10:05','2','1','0.42231975442014613');
INSERT INTO words VALUES('3587','1','limited','limited','5','ограниченный','','Interfaces provide a {limited} form of multiple inheritance.','2025-08-31 20:32:27','2026-02-21 13:04:32','12','10','0.5358394920228416');
INSERT INTO words VALUES('3588','1','uppercase','uppercase','99','верхний регистр, прописные буквы','','By convention, interface names start with an {uppercase} \"I\".','2025-08-31 20:32:27','2026-01-18 13:05:42','100','100','0.5843287562805496');
INSERT INTO words VALUES('3589','1','inheriting','inheriting','5','наследование; наследовать','','As with classes, {inheriting} from interfaces allows you to substitute instances of a type that implements the interface wherever an instance of that interface is required.','2025-08-31 20:32:27','2026-02-14 12:41:50','2','1','0.41223822758741513');
INSERT INTO words VALUES('3590','1','creation','creation','5','создание; создавать','','This enables the {creation} of loosely coupled and flexible applications, such as DI containers or mock testing.','2025-08-31 20:32:27','2026-02-23 13:28:28','15','13','0.4536726926021955');
INSERT INTO words VALUES('3591','1','loosely','loosely','4','свободно, слабо','','This enables the creation of {loosely} coupled and flexible applications, such as DI containers or mock testing.','2025-08-31 20:32:27','2026-04-23 12:52:00','43','41','0.031648810982377096');
INSERT INTO words VALUES('3592','1','coupled','coupled','4','связанный, соединённый; связывать','','This enables the creation of loosely {coupled} and flexible applications, such as DI containers or mock testing.','2025-08-31 20:32:27','2026-04-24 11:43:07','45','43','0.7972260078389439');
INSERT INTO words VALUES('3593','1','flexible','flexible','99','гибкий, эластичный, адаптивный','','This enables the creation of loosely coupled and {flexible} applications, such as DI containers or mock testing.','2025-08-31 20:32:27','2026-01-18 13:11:12','100','100','0.19415940548680669');
INSERT INTO words VALUES('3594','1','applications','applications','99','приложения','','This enables the creation of loosely coupled and flexible {applications}, such as DI containers or mock testing.','2025-08-31 20:32:27','2025-09-22 13:58:32','100','100','0.13940678643007465');
INSERT INTO words VALUES('3595','1','containers','containers','99','контейнеры, ёмкости','','This enables the creation of loosely coupled and flexible applications, such as DI {containers} or mock testing.','2025-08-31 20:32:27','2026-04-24 12:36:28','100','100','0.15188449821610422');
INSERT INTO words VALUES('3596','1','mock','mock','5','мок, имитация, заглушка; имитировать, подменять','','This enables the creation of loosely coupled and flexible applications, such as DI containers or {mock} testing.','2025-08-31 20:32:27','2026-02-15 13:05:43','3','2','0.8911836369812336');
INSERT INTO words VALUES('3597','1','testing','testing','99','тестирование; тестировать','','This enables the creation of loosely coupled and flexible applications, such as DI containers or mock {testing}.','2025-08-31 20:32:27','2026-04-24 12:34:28','100','100','0.6641110392884454');
INSERT INTO words VALUES('3598','1','nested','nested','4','вложенный','','derived types do not have access unless they are {nested} within the base class.','2025-08-31 20:32:27','2026-04-22 16:46:32','41','39','0.06424019212298113');
INSERT INTO words VALUES('3599','1','current','current','5','текущий','','- protected members are visible only within the {current} class and in derived classes.','2025-08-31 20:32:27','2026-03-03 16:22:40','26','24','0.6476500804048498');
INSERT INTO words VALUES('3600','1','instantiated','instantiated','5','созданный экземпляр; создавать экземпляр','','An abstract class is a class with the `abstract` modifier, which indicates that the class cannot be {instantiated} directly and serves only as a base class.','2025-08-31 20:32:27','2026-02-24 16:21:07','16','15','0.04552985638895059');
INSERT INTO words VALUES('3601','1','missing','missing','5','отсутствующий, недостающий; пропускать, упускать','','Its members may have {missing} or incomplete implementations.','2025-08-31 20:32:27','2026-02-14 13:06:11','2','1','0.28469907146384854');
INSERT INTO words VALUES('3602','1','incomplete','incomplete','5','неполный, незавершённый','','Its members may have missing or {incomplete} implementations.','2025-08-31 20:32:27','2026-02-26 15:53:13','19','17','0.2869058188860359');
INSERT INTO words VALUES('3603','1','mapping','mapping','3','сопоставление, отображение; сопоставлять, отображать','','An abstract class can inherit from a base class or implement interfaces, {mapping} their methods to abstract methods.','2025-08-31 20:32:27','2026-04-22 21:12:10','13','11','0.5804319107722788');
INSERT INTO words VALUES('3604','1','fully','fully','99','полностью, целиком','','Abstract classes can also contain {fully} implemented members and override virtual methods.','2025-08-31 20:32:27','2026-04-22 22:03:24','100','100','0.19898120425546653');
INSERT INTO words VALUES('3605','1','covariant','covariant','5','ковариантный','','Each type parameter of a generic delegate must be marked as {covariant} or contravariant.','2025-08-31 20:32:27','2026-02-14 12:41:40','2','1','0.041442127936931444');
INSERT INTO words VALUES('3606','1','contravariant','contravariant','5','контравариантный','','Each type parameter of a generic delegate must be marked as covariant or {contravariant}.','2025-08-31 20:32:27','2026-02-15 13:15:14','3','2','0.4659149381014658');
INSERT INTO words VALUES('3607','1','Invariant','invariant','99','инвариант, инвариантный','','- {Invariant} - the type parameter cannot be changed, and this approach is used by default.','2025-08-31 20:32:27','2026-01-18 21:56:57','100','100','0.09672832963683486');
INSERT INTO words VALUES('3608','1','approach','approach','5','подход, метод, способ; подходить, приближаться','','- Invariant - the type parameter cannot be changed, and this {approach} is used by default.','2025-08-31 20:32:27','2026-04-22 21:08:28','96','94','0.20524833743017942');
INSERT INTO words VALUES('3609','1','converted','converted','5','преобразованный, конвертированный; преобразовывать, конвертировать','','- Contravariant - the type parameter can be {converted} to a derived class and is marked with the `in` keyword.','2025-08-31 20:32:27','2026-02-23 13:29:38','15','13','0.6284969035801449');
INSERT INTO words VALUES('3610','1','appear','appear','5','появляться, возникать, отображаться','','It can only {appear} in input positions, such as method parameters.','2025-08-31 20:32:27','2026-02-23 13:33:54','15','13','0.5267395363438311');
INSERT INTO words VALUES('3611','1','positions','positions','99','позиции, места; позиционировать, размещать','','It can only appear in output {positions}, such as method return values.','2025-08-31 20:32:27','2026-04-23 12:55:53','100','100','0.38031946064934086');
INSERT INTO words VALUES('3612','1','output','output','99','вывод, выходной; выводить','','It can only appear in {output} positions, such as method return values.','2025-08-31 20:32:27','2026-01-18 13:03:47','100','100','0.49409588006706523');
INSERT INTO words VALUES('3613','1','invariance','invariance','5','инвариантность, неизменность','','You cannot use {invariance} with the `ref` and `out` keywords.','2025-08-31 20:32:27','2026-02-22 13:44:19','13','12','0.748207001712366');
INSERT INTO words VALUES('3614','1','Chars','chars','99','символы (char)','','{Chars} in the .NET Framework are always represented as 16-bit Unicode codes and are instances of the `Char` structure.','2025-08-31 20:32:27','2025-09-02 21:12:07','100','100','0.979286292548558');
INSERT INTO words VALUES('3615','1','Framework','framework','4','инфраструктура, платформа','','Chars in the .NET {Framework} are always represented as 16-bit Unicode codes and are instances of the `Char` structure.','2025-08-31 20:32:27','2026-04-22 22:52:21','41','39','0.16081643026398162');
INSERT INTO words VALUES('3616','1','represented','represented','5','представленный; представлять','','Chars in the .NET Framework are always {represented} as 16-bit Unicode codes and are instances of the `Char` structure.','2025-08-31 20:32:27','2026-02-14 12:46:52','2','1','0.5594611769164551');
INSERT INTO words VALUES('3617','1','Unicode','unicode','99','Unicode, Юникод','','Chars in the .NET Framework are always represented as 16-bit {Unicode} codes and are instances of the `Char` structure.','2025-08-31 20:32:27','2026-01-18 21:59:41','100','100','0.968780966446531');
INSERT INTO words VALUES('3618','1','codes','codes','99','коды, шифры; кодировать, шифровать','','Chars in the .NET Framework are always represented as 16-bit Unicode {codes} and are instances of the `Char` structure.','2025-08-31 20:32:27','2026-01-17 16:00:28','100','100','0.9843005630972801');
INSERT INTO words VALUES('3619','1','MinValue','minvalue','99','MinValue, минимальное значение','','The `System.Char` type contains two public immutable fields: the constants `{MinValue}` and `MaxValue`.','2025-08-31 20:32:27','2025-09-07 16:47:01','100','100','0.32681971260050285');
INSERT INTO words VALUES('3620','1','MaxValue','maxvalue','99','MaxValue, максимальное значение','','The `System.Char` type contains two public immutable fields: the constants `MinValue` and `{MaxValue}`.','2025-08-31 20:32:27','2025-09-07 17:15:03','100','100','0.4987400243978389');
INSERT INTO words VALUES('3621','1','vice','vice','5','1','','There are three ways to convert various numeric types to instances of the `Char` type, and {vice} versa: type casting, using the `Convert` type (which contains several static methods), or using the `IConvertible` interface, which defines methods such as `ToUInt16` and `ToChar`.','2025-08-31 20:32:27','2026-04-22 21:12:15','96','94','0.31485662452397556');
INSERT INTO words VALUES('3622','1','versa','versa','99','1','','There are three ways to convert various numeric types to instances of the `Char` type, and vice {versa}: type casting, using the `Convert` type (which contains several static methods), or using the `IConvertible` interface, which defines methods such as `ToUInt16` and `ToChar`.','2025-08-31 20:32:27','2025-09-02 21:09:26','100','100','0.7301482993458848');
INSERT INTO words VALUES('3623','1','IConvertible','iconvertible','99','IConvertible, интерфейс IConvertible','','There are three ways to convert various numeric types to instances of the `Char` type, and vice versa: type casting, using the `Convert` type (which contains several static methods), or using the `{IConvertible}` interface, which defines methods such as `ToUInt16` and `ToChar`.','2025-08-31 20:32:27','2026-01-18 22:00:46','100','100','0.3164249912988627');
INSERT INTO words VALUES('3624','1','ToUInt','touint','99','ToUInt, метод ToUInt','','There are three ways to convert various numeric types to instances of the `Char` type, and vice versa: type casting, using the `Convert` type (which contains several static methods), or using the `IConvertible` interface, which defines methods such as `{ToUInt}16` and `ToChar`.','2025-08-31 20:32:27','2025-09-02 21:03:07','100','100','0.4314070022026142');
INSERT INTO words VALUES('3625','1','ToChar','tochar','99','ToChar, метод ToChar','','There are three ways to convert various numeric types to instances of the `Char` type, and vice versa: type casting, using the `Convert` type (which contains several static methods), or using the `IConvertible` interface, which defines methods such as `ToUInt16` and `{ToChar}`.','2025-08-31 20:32:27','2025-09-02 21:07:54','100','100','0.0696375594191603');
INSERT INTO words VALUES('3626','1','UTF','utf','99','UTF, ЮТФ','','String is an immutable reference type that represents a sequence of {UTF}‑16 characters.','2025-08-31 20:32:27','2025-09-02 01:41:37','100','100','0.8420814814437939');
INSERT INTO words VALUES('3627','1','characters','characters','99','символы, персонажи; характеризовать','','String is an immutable reference type that represents a sequence of UTF‑16 {characters}.','2025-08-31 20:32:27','2026-01-17 20:54:17','100','100','0.42930949612456326');
INSERT INTO words VALUES('3628','1','Hi','hi','99','привет','','String s = \"{Hi}\" + \" \" + \"there.\";','2025-08-31 20:32:27','2025-09-02 21:11:12','100','100','0.8163504365983889');
INSERT INTO words VALUES('3629','1','there.','there.','99','там, «there»','','String s = \"Hi\" + \" \" + \"{there.}\";','2025-08-31 20:32:27','2026-01-18 21:54:05','100','100','0.5876194449026318');
INSERT INTO words VALUES('3630','1','Concatenation','concatenation','5','сцепление, каскадное соединение','','{Concatenation} of literals and constant expressions is performed at compile time;','2025-08-31 20:32:27','2026-02-15 13:17:19','3','2','0.8958996226041575');
INSERT INTO words VALUES('3631','1','literals','literals','99','литералы, константы','','Concatenation of {literals} and constant expressions is performed at compile time;','2025-08-31 20:32:27','2026-04-24 11:48:49','100','100','0.7111059946111459');
INSERT INTO words VALUES('3632','1','performed','performed','99','выполненный; выполнять','','Concatenation of literals and constant expressions is {performed} at compile time;','2025-08-31 20:32:27','2026-04-22 22:55:07','100','100','0.5305999829718843');
INSERT INTO words VALUES('3633','1','literal','literal','99','литерал, буквальный, дословный','','only a single {literal} is stored in the metadata.','2025-08-31 20:32:27','2026-04-24 12:34:19','100','100','0.8015750532984501');
