INSERT INTO words VALUES('3644','1','raw','raw','4','необработанный, сырой; болезненный','','He ate {raw} fish, studied {raw} data, and had {raw} hands from the cold.','2025-08-31 20:32:27','2026-04-22 16:56:08','41','39','0.6944611404970857');
