INSERT INTO words VALUES('3653','1','pooling','pooling','5','объединение; объединять','','String {pooling} is a mechanism in which each string is stored only once.','2025-08-31 22:38:05','2026-02-24 13:34:04','16','15','0.5694776098890952');
