INSERT INTO words VALUES('3659','1','modifying','modifying','4','модификация, изменение; модифицировать, изменять','','This means that {modifying} the contents of a `StringBuilder` instance does not create new objects on the managed heap.','2025-08-31 22:38:05','2026-04-24 11:48:59','45','43','0.6429135339734271');
