INSERT INTO words VALUES('3667','1','grows','grows','99','расти, увеличиваться','','When the string {grows} beyond the previously allocated character array, `StringBuilder` automatically allocates memory for a new, larger array, copies the characters, and continues working with the new array.','2025-08-31 22:38:05','2026-04-24 11:50:16','100','100','0.2751207959606506');
