INSERT INTO words VALUES('4084','1','Encapsulation','encapsulation','99','Инкапсуляция','','- {Encapsulation} — a language mechanism that binds code and data together and protects them from external interference or incorrect use.','2025-09-20 12:06:57','2026-01-19 17:40:26','100','100','0.650481447251962');
